import{_ as n,c as i,o as a,a2 as r}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Datenschutzerklärung","description":"qDiff sammelt keine Daten. Lesen Sie, was die App auf Ihrem Mac liest und wie Käufe abgewickelt werden.","frontmatter":{"title":"Datenschutzerklärung","description":"qDiff sammelt keine Daten. Lesen Sie, was die App auf Ihrem Mac liest und wie Käufe abgewickelt werden."},"headers":[],"relativePath":"de/privacy/index.md","filePath":"de/privacy/index.md","lastUpdated":1794296122000}'),t={name:"de/privacy/index.md"};function s(d,e,l,u,h,o){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to &quot;Datenschutzerklärung&quot;">​</a></h1><p><em>Zuletzt aktualisiert: 6. November 2026</em></p><p><strong>Kurz gesagt: qDiff erhebt keine personenbezogenen Daten.</strong> Es ist ein lokales Werkzeug. Ihre Dateien bleiben auf Ihrem Mac.</p><h2 id="was-qdiff-liest" tabindex="-1">Was qDiff liest <a class="header-anchor" href="#was-qdiff-liest" aria-label="Permalink to &quot;Was qDiff liest&quot;">​</a></h2><p>qDiff öffnet nur die Dateien und Ordner, die Sie in der App auswählen, und verarbeitet sie auf Ihrem Gerät, um den Vergleich anzuzeigen. Wenn Sie den Zugriff auf einen Ordner erlauben, bleibt dieser Zugriff zu Ihrer Bequemlichkeit erhalten und kann jederzeit in den Einstellungen entfernt werden. Nichts wird an uns hochgeladen.</p><h2 id="was-wir-nicht-tun" tabindex="-1">Was wir nicht tun <a class="header-anchor" href="#was-wir-nicht-tun" aria-label="Permalink to &quot;Was wir nicht tun&quot;">​</a></h2><ul><li>Wir erheben keine Namen, E-Mail-Adressen oder Nutzungsstatistiken.</li><li>Wir verfolgen Sie nicht über Apps oder Websites hinweg.</li><li>Wir verlangen kein Konto und keine Anmeldung.</li><li>Wir zeigen keine Werbung und binden keine Analyse- oder Tracking-Dienste Dritter ein.</li><li>Wir synchronisieren oder sichern Ihre Dateien auf keinem Server.</li></ul><h2 id="netzwerkzugriff" tabindex="-1">Netzwerkzugriff <a class="header-anchor" href="#netzwerkzugriff" aria-label="Permalink to &quot;Netzwerkzugriff&quot;">​</a></h2><p>qDiff arbeitet offline. Die einzige optionale Netzwerkanfrage ist die appinterne Seite „Weitere Apps“, die eine öffentliche Liste von Apps lädt. Diese Anfrage enthält keine Informationen über Sie, Ihre Dateien oder Ihr Gerät, und es werden keine Nutzungsdaten zurückgesendet.</p><h2 id="kaufe" tabindex="-1">Käufe <a class="header-anchor" href="#kaufe" aria-label="Permalink to &quot;Käufe&quot;">​</a></h2><p>Der optionale einmalige Kauf wird vollständig über den Mac App Store und Ihre Apple ID abgewickelt. Wir sehen Ihre Zahlungsdaten niemals. Sie können einen Kauf in den Einstellungen innerhalb der App wiederherstellen.</p><h2 id="diese-website" tabindex="-1">Diese Website <a class="header-anchor" href="#diese-website" aria-label="Permalink to &quot;Diese Website&quot;">​</a></h2><p>Diese Website besteht aus statischen Seiten. Sie hat keine Anmeldung, keine Analyse und keine Werbe-Cookies. Beim Öffnen einer Seite müssen Sie uns nichts mitteilen.</p><h2 id="kinder" tabindex="-1">Kinder <a class="header-anchor" href="#kinder" aria-label="Permalink to &quot;Kinder&quot;">​</a></h2><p>qDiff richtet sich nicht an Kinder und erhebt wissentlich keine Informationen von irgendjemandem.</p><h2 id="anderungen" tabindex="-1">Änderungen <a class="header-anchor" href="#anderungen" aria-label="Permalink to &quot;Änderungen&quot;">​</a></h2><p>Falls sich diese Erklärung einmal ändert, aktualisieren wir diese Seite und das oben genannte Datum. Jede Änderung, die betrifft, was die App liest, wird auch in der App selbst beschrieben.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Fragen zum Datenschutz? Schreiben Sie an <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>.</p>',19)])])}const k=n(t,[["render",s]]);export{c as __pageData,k as default};
